INSERT INTO "producer" ("id", "user_id", "nip", "name", "country_code", "rating", "review_count", "technology", "verification_status", "created_at", "updated_at", "deleted_at", "production_scale", "inquiry_response_time_label", "showroom_visit_available", "showroom_visit_note", "description") VALUES ('e0030000-0000-4000-8000-000000000102', 'catalog-import:framedev', 'CATALOG-FRAMEDEV', 'FrameDEV', 'PL', NULL, 0, 'modulowa-stal-lekka', 'not_submitted', '2026-10-21T17:43:47.537Z'::timestamptz, '2026-10-22T13:30:26.167Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Producent całorocznych domów na prefabrykowanym szkielecie stalowym LGS (ocynkowane profile cienkościenne): konstrukcja powstaje w hali na liniach CNC, a na działce jest montowana w kilka dni. Oferta obejmuje gotowe projekty z serii Homekoncept i Z500, każdy w trzech pakietach wykończenia od stanu deweloperskiego po pełne wyposażenie. Płatności są podzielone na osiem etapów, a cena materiałów zostaje zamrożona po podpisaniu umowy. Projekt można zaadaptować do działki i potrzeb inwestora.') ON CONFLICT DO NOTHING;
INSERT INTO "producer_delivery_country" ("producer_id", "country_code", "created_at") VALUES ('e0030000-0000-4000-8000-000000000102', 'PL', '2026-10-21T17:43:47.537Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_member" ("id", "producer_id", "user_id", "added_by", "created_at") VALUES ('5da8f2dd-f924-4a58-82bc-cfae47d67e21', 'e0030000-0000-4000-8000-000000000102', 'catalog-import:framedev', NULL, '2026-10-21T17:43:47.537Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('f6c54f09-9e9c-4b97-9eff-9f28a4f8ad41', 'e0030000-0000-4000-8000-000000000102', 'en', 'Producer of year-round houses on a prefabricated LGS steel frame (galvanised light-gauge profiles): the structure is made in a factory on CNC lines and assembled on site within days. The range covers ready-made designs from the Homekoncept and Z500 series, each in three finishing packages from shell-and-core to fully equipped. Payments are split into eight stages and the material price is frozen once the contract is signed. A design can be adapted to the plot and the investor''s needs.', NULL, NULL, '2026-10-21T17:43:47.537Z'::timestamptz, '2026-10-22T13:30:26.167Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('9efff927-d54c-47b8-9934-c0618bbb1961', 'e0030000-0000-4000-8000-000000000102', 'de', 'Hersteller ganzjährig nutzbarer Häuser auf vorgefertigtem LGS-Stahlskelett (verzinkte Leichtstahlprofile): Die Konstruktion entsteht im Werk auf CNC-Linien und wird auf dem Grundstück innerhalb weniger Tage montiert. Das Angebot umfasst fertige Entwürfe der Serien Homekoncept und Z500, jeweils in drei Ausbaupaketen vom Bauträgerstandard bis zur vollständigen Ausstattung. Die Zahlung ist in acht Etappen aufgeteilt, und der Materialpreis wird mit Vertragsabschluss eingefroren. Ein Entwurf kann an das Grundstück und die Wünsche des Bauherrn angepasst werden.', NULL, NULL, '2026-10-21T17:43:47.537Z'::timestamptz, '2026-10-22T13:30:26.167Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('988fdd88-110b-4444-a539-4eac067f2a90', 'e0030000-0000-4000-8000-000000000102', 'nl', 'Producent van jaarrondwoningen op een geprefabriceerd LGS-staalskelet (verzinkte lichtgewicht profielen): de constructie wordt in de fabriek op CNC-lijnen gemaakt en binnen enkele dagen op de bouwplaats gemonteerd. Het aanbod omvat kant-en-klare ontwerpen uit de series Homekoncept en Z500, elk in drie afwerkingspakketten van casco tot volledig uitgerust. De betaling is verdeeld over acht etappes en de materiaalprijs wordt bij ondertekening van het contract bevroren. Een ontwerp kan worden aangepast aan de kavel en de wensen van de bouwheer.', NULL, NULL, '2026-10-21T17:43:47.537Z'::timestamptz, '2026-10-22T13:30:26.167Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('9c87e504-8de5-4a64-ae6b-80e53fd60f7c', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'en', 'Feasibility and formal requirements depend on the specific plot and local regulations.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('770a3199-1d74-48f6-900a-257e3705d368', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'de', 'Realisierbarkeit und formale Anforderungen hängen vom konkreten Grundstück und den örtlichen Vorgaben ab.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('eea7d9ec-ebb7-41fb-ae26-04cfba73092d', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'nl', 'Haalbaarheid en formele vereisten zijn afhankelijk van het specifieke perceel en de lokale voorschriften.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
